class Transformer extends Component{constructor(d={}){super({...d,type:'transformer',terminals:[{id:'P1',kind:'primary'},{id:'P2',kind:'primary'},{id:'S1',kind:'phase'},{id:'S2',kind:'neutral'},{id:'S3',kind:'phase'}]});this.heightCells=Math.max(10,d.heightCells||10);}}
class Fuse extends Component{constructor(d={}){super({...d,type:'fuse',terminals:d.terminals||[{id:'A'},{id:'B'}]});this.rating=d.rating||'10 A';this.blown=!!d.blown;}}
class Junction extends Component{constructor(d={}){super({...d,label:d.label??d.id,showId:d.showId??false,showLabel:d.showLabel??false,type:'junction',terminals:d.terminals||[{id:'J'}]});}}
class AdjTip extends Component{constructor(d={}){const rows=Math.max(1,Number(d.rows)||2),multiple=!!d.multipleTips,tipCount=multiple?rows:1,terminals=[...Array.from({length:rows},(_,i)=>({id:`LINE${i+1}`})),...Array.from({length:tipCount},(_,i)=>({id:`TIP${i+1}`}))];super({...d,rotation:d.rotation??0,type:'adjTip',terminals});this.rows=rows;const height=Number(d.heightCells??d.widthCells);this.heightCells=[1,2,3].includes(height)?height:1;this.rowSpacingCells=Number(d.rowSpacingCells)===2?2:1;this.lineLabels=Array.from({length:rows},(_,i)=>String(d.lineLabels?.[i]??i+1));this.multipleTips=multiple;this.tipPositions=Array.from({length:tipCount},(_,i)=>Math.max(0,Math.min(rows,Number(d.tipPositions?.[i])||0)));}}
class RemoteConnector extends Component{constructor(d={}){super({...d,rotation:d.rotation??0,label:d.label??d.id,showId:d.showId??false,showLabel:d.showLabel??true,type:'remoteConnector',terminals:d.terminals||[{id:'J'}]});this.linkedId=d.linkedId||null;this.direction=d.direction==='out'?'out':'in';this.styleId=d.styleId||'RED';}}
