const componentClasses={powerSource:PowerSource,coil:Coil,contact:Contact,lamp:Lamp,motor:Motor,transformer:Transformer,fuse:Fuse,junction:Junction,adjTip:AdjTip,remoteConnector:RemoteConnector,counter:Counter};
